"""
Usage: python getlang.py "path\\to\\subtitle.srt"
Supported languages: en, es, pt

Dependencies:
    pip install rich git+https://github.com/vevv/subby.git
"""
import re
import sys
from pathlib import Path
from collections import Counter

from rich.console import Console
from subby import SubRipFile

console = Console(color_system="truecolor")

ENGLISH_LANG_TAG_PATTERN = re.compile(r'[._ ]en(-US|-GB)?(\[(sdh|forced)\])?$', re.IGNORECASE)
SPANISH_LANG_TAG_PATTERN = re.compile(r'[._ ]es(-(ES|419))?(\[(sdh|forced)\])?$', re.IGNORECASE)
TAG_STRIP_PATTERN = re.compile(r'</?i>|</?u>|</?b>|{\s*\\an[1-9]\s*}|<font.*?>|</font>')

class FileNamePatterns:
    NUMBERED_SUFFIX = re.compile(r"^(.*?)-(\d{1,2})$", re.IGNORECASE)
    
class SDHPatterns:
    BRACKET_PATTERN = re.compile(r"\[.*?\]")
    PARENTHESIS_PATTERN = re.compile(r"\(.*?\)")
    SPEAKER_PATTERN = re.compile(r"^[A-Za-z0-9_]+:\s")  # e.g. JOHN: Hello
    MUSIC_PATTERN = re.compile(r"[♪♫]")

