def get_subtitle_files(directory: str | Path, extension: str | None = None) -> list[Path]:
    """Get all subtitle files in the specified directory. If extension is None, get all .srt and .vtt"""
    path = Path(directory)
    if extension is None:
        return list(path.glob("*.srt")) + list(path.glob("*.vtt"))
    if not extension:
        raise ValueError("Extension must not be empty")
    return list(path.rglob(f"*.{extension.lstrip('.')}"))


def strip_numbered_suffix(file_path: str | Path) -> str:
    # strips a 1 or 2 digit numbered suffix e.g. "-1" or "-20"
    # from the end of the string if it exists
    if not file_path:
        return file_path

    path = Path(file_path)
    stem = path.stem
    suffix = path.suffix
    m = FileNamePatterns.NUMBERED_SUFFIX.match(stem)
    new_stem = m.group(1) if m else stem
    return f"{new_stem}{suffix}"


def get_srt_content(file_path: str | Path, strip_tags: bool = False) -> str:
    # get the content of the SRT file as one continuous string excluding timestamps, indicies,
    # and optionally excluding tags
    file_path = Path(file_path)
    if not file_path or file_path.suffix.lower() != ".srt":
        return ""
        
    srt = SubRipFile.from_string(file_path.read_text(encoding='utf-8'))
    if not srt:
        return ""
    
    content = ""
    for line in srt:
        stripped_line_content = line.content.replace("\n", " ") + " "
        stripped_line_content = re.sub(r"\s+", " ", stripped_line_content)
        if strip_tags:
            stripped_line_content = TAG_STRIP_PATTERN.sub("", stripped_line_content)
        content += stripped_line_content
    return content.strip()
    
    
def get_srt_words(srt_content: str, strip_tags: bool = True) -> list[str] | None:
    # remove punctuation and non-letter/number characters so words are always separated by
    # white space and can be mapped properly
    srt_content_stripped = re.sub(r"[\"\'…\[\]\(\):,\.!?¿¡«»“”;‐–—⁃]+", " ", srt_content)
    # hyphens must be preserved for certain eclitics, so we only replace hyphens
    # that have white space on either side
    dash_pattern = r"(?:(?<= )-(?=\w)|(?<=\w)-(?= ))"
    srt_content_stripped = re.sub(dash_pattern, " ", srt_content_stripped)
    # strip remaining white space and collapse multiple white space characters into one
    srt_content_stripped = re.sub(r"\s+", " ", srt_content_stripped).strip()
    return srt_content_stripped.split()


def get_unique_filename(file_path: str | Path, used_filenames: set[str] = None) -> Path:
    """
    Get a unique filename by appending incrementing numeric suffixes.
    If the filename ends with -N (1-2 digits), it increments N until no conflict.
    """
    file_path = Path(file_path)
    path_str = str(file_path)
    if not used_filenames:
        used_filenames = set()

    # if the path doesn't exist and is not used, return as is
    if not file_path.exists() and path_str not in used_filenames:
        used_filenames.add(path_str)
        return file_path
    
    stem = file_path.stem
    m = FileNamePatterns.NUMBERED_SUFFIX.match(stem)

    if m:
        # file already ends in -N, so we start incrementing from N+1
        main_stem = m.group(1)
        i = int(m.group(2)) + 1
    else:
        # file has no numeric suffix, so we start with -1
        main_stem = stem
        i = 1
    
    while True:
        new_file_path = file_path.parent / f"{main_stem}-{i}{file_path.suffix}"
        new_path_str = str(new_file_path)
        if not new_file_path.exists() and new_path_str not in used_filenames:
            used_filenames.add(new_path_str)
            return new_file_path

        i += 1


def get_dialect(lang_tag: str, data: bytes | str | Path, converter_type: str = None) -> tuple[str, dict]:
    """
    Gets the correct dialect for the given language tag and subtitle content.

    If the subtitle content is not in .srt format, you can provide a converter type
    and the function will convert the content to .srt format before analysis.

    Supported dialects: en, es

    Args:
        lang_tag (str): The language tag to analyze, e.g. "en-US", "en-GB", "es-ES", "es-419".
        data (bytes | str | Path): The subtitle content as bytes, string, or a Path to a subtitle file.
        converter_type (str, optional): The type of subtitle file if the content is not in .srt format,
                                        e.g. "smpte", "vtt", "sami". Defaults to None.
    Returns:
        str: The correct dialect for the given language tag and subtitle content.
    """
    dialect_hits = {}
    base_tag = lang_tag.split("-")[0]
    if base_tag.lower() not in DIALECT_WORD_MAP:
        return lang_tag, dialect_hits
    # get the subtitle content as a string with tags stripped
    srt_content = get_srt_content(data, True).lower()
    # split the content into words so we can match them
    srt_words = get_srt_words(srt_content)
    word_counts = Counter(srt_words)
    # iterate only the "pt" entry and get dialect, string_type and each string
    dialect_hit_map = {}
    for dialect, types in DIALECT_WORD_MAP[base_tag].items():
        total = 0
        dialect_hit_map[dialect] = {}

        words_set = {w.lower() for w in types.get("word", set())}
        phrases_set = {p.lower() for p in types.get("phrase", set())}
        verbs_set = {v.lower() for v in types.get("verb", set())}

        # count word matches
        if words_set:
            for w in words_set:
                word_count = word_counts.get(w, 0)
                if word_count > 0:
                    dialect_hit_map[dialect][w] = word_count
                total += word_count

        # count phrases using regex
        for phrase in phrases_set:
            if not phrase:
                continue
            pattern = rf"(?<!\w){re.escape(phrase)}(?!\w)"
            phrase_count = len(re.findall(pattern, srt_content))
            if phrase_count > 0:
                dialect_hit_map[dialect][phrase] = phrase_count
            total += phrase_count

        # count verbs using preceding pronoun
        if verbs_set:
            # choose preceding pronouns per dialect/language
            pre_verb = ""
            if base_tag == "pt":
                if dialect == "pt-PT":
                    pre_verb = "tu"
                elif dialect == "pt-BR":
                    pre_verb = "você"

            if pre_verb:
                for i in range(1, len(srt_words)):
                    if srt_words[i] in verbs_set and srt_words[i - 1] == pre_verb:
                        verb_token = srt_words[i]
                        dialect_hit_map[dialect][f"{pre_verb} {verb_token}"] = dialect_hit_map[dialect].get(f"{pre_verb} {verb_token}", 0) + 1
                        total += 1
        dialect_hits[dialect] = total

    best_count = max(dialect_hits.values(), default=0)

    # if no matches found, return the original tag
    if best_count == 0:
        return lang_tag
    # get the dialect with the most hits, if it's a tie, prefer the given tag
    best_dialect = max(dialect_hits, key=lambda d: (dialect_hits[d], d == lang_tag))
    
    return best_dialect, dialect_hits, dialect_hit_map


def main():
    if len(sys.argv) < 2:
        console.print("A path to a subtitle file is required as an argument.")
        return
    # allow file paths to be input without quotations that contain spaces
    file = Path(" ".join(sys.argv[1:]))
    if not file:
        console.print(
            f"A valid path to a subtitle file is required as an argument.\n"
            f"Got: {file}"
        )
        return
    if not file.exists():
        console.print(f"'{file}' does not exist.")
        return
    lang_tag = file.stem.split(".")[-1].split("[")[0]
    base_tag = lang_tag.split("-")[0]
    if base_tag not in DIALECT_WORD_MAP:
        console.print(
            f"'{base_tag}' is not a supported language."
            f"Supported languages: en, es, pt"
        )
        return
    dialect, dialect_hits, dialect_hit_map = get_dialect(lang_tag, file)
    console.print("\nDialect hits:")
    for d in dialect_hit_map:
        console.print(f"{d}: {dialect_hit_map.get(d)}", highlight=False)
    
    color = "green" if dialect == lang_tag else "yellow"
    console.print(
        f"\nDetermined dialect for [{color}]{lang_tag}[/] -> [green]{dialect}[/]"
        f" ({', '.join(f'[white]{d}[/]: {c}' for d, c in dialect_hits.items())})",
        highlight=False,
    )


if __name__ == "__main__":
    main()
